import React from "react";
import {
  FaCheckCircle,
  FaExclamationTriangle,
  FaTimesCircle,
  FaInfoCircle,
} from "react-icons/fa";

const BudgetAlerts = ({
  goalAmount = 150000,
  currentSavings = 0,
}) => {
  const progress = (currentSavings / goalAmount) * 100;
  const remaining = Math.max(goalAmount - currentSavings, 0);

  const alerts = [];

  // Goal Progress
  if (progress >= 100) {
    alerts.push({
      title: "Goal Achieved 🎉",
      message: "Congratulations! You have reached your savings goal.",
      color: "bg-green-500",
      icon: <FaCheckCircle className="text-2xl text-white" />,
    });
  } else if (progress >= 80) {
    alerts.push({
      title: "Almost There",
      message: "Excellent! You have completed more than 80% of your goal.",
      color: "bg-yellow-500",
      icon: <FaExclamationTriangle className="text-2xl text-white" />,
    });
  } else {
    alerts.push({
      title: "Keep Saving",
      message: "You're making progress. Stay consistent with your savings.",
      color: "bg-blue-500",
      icon: <FaInfoCircle className="text-2xl text-white" />,
    });
  }

  // Remaining Amount
  if (remaining > 0) {
    alerts.push({
      title: "Remaining Amount",
      message: `You still need ₹${remaining.toLocaleString()} to reach your goal.`,
      color: "bg-purple-500",
      icon: <FaInfoCircle className="text-2xl text-white" />,
    });
  }

  // Suggestion
  if (progress < 80) {
    alerts.push({
      title: "Savings Tip",
      message:
        "Reduce unnecessary expenses like shopping or dining out to reach your goal faster.",
      color: "bg-indigo-500",
      icon: <FaInfoCircle className="text-2xl text-white" />,
    });
  }

  return (
    <div className="bg-slate-800 rounded-3xl p-6 shadow-xl border border-slate-700 mt-8">
      <h2 className="text-3xl font-bold text-white mb-6">
        🎯 Goal Alerts
      </h2>

      <div className="space-y-4">
        {alerts.map((alert, index) => (
          <div
            key={index}
            className={`${alert.color} rounded-2xl p-5 flex items-start gap-4`}
          >
            {alert.icon}

            <div>
              <h3 className="text-xl font-bold text-white">
                {alert.title}
              </h3>

              <p className="text-white mt-1">
                {alert.message}
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Progress Bar */}

      <div className="mt-8">

        <div className="flex justify-between mb-2">

          <span className="text-white">
            Goal Progress
          </span>

          <span className="text-blue-400 font-bold">
            {progress.toFixed(1)}%
          </span>

        </div>

        <div className="w-full bg-slate-700 rounded-full h-5 overflow-hidden">

          <div
            className={`${
              progress >= 100
                ? "bg-green-500"
                : progress >= 80
                ? "bg-yellow-500"
                : "bg-blue-500"
            } h-full transition-all duration-700`}
            style={{
              width: `${Math.min(progress, 100)}%`,
            }}
          />

        </div>

      </div>

    </div>
  );
};

export default BudgetAlerts;